
/* Generated by RED (red/iss.py): native reference run of secp256r1.mmod's c_model.
 * Prints one 32-bit word per line, lowercase hex — the exact format Spike's
 * +signature dump uses, so the two are compared line by line. */
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define RED_WORDS   16
#define RED_NVEC    100000
#define RED_NCORNER 4
#define RED_BLOCK   1024

/* ---- designer-supplied C reference model ---- */
#include <stdint.h>
#include <string.h>
/* mnemonic secp256r1.mmod -> secp256r1_mmod_model; in[0..15]=512-bit X, out[0..7]=X mod p256, out[8..15]=0 */
static const uint32_t MM_P256[8] = {0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFFu, 0x00000000u,
                                    0x00000000u, 0x00000000u, 0x00000001u, 0xFFFFFFFFu};
/* FIPS 186-4 D.2.3 terms as source-word indices into c[0..16] (index 16 = constant zero), word 0 first.
   Pass order: s1, s1, s2, s2, s3, s4, d1, d2, d3, d4 (s1, s2 added twice = 2*s1, 2*s2). */
static const unsigned char MM_TERM[10][8] = {
    {16, 16, 16, 11, 12, 13, 14, 15},
    {16, 16, 16, 11, 12, 13, 14, 15},
    {16, 16, 16, 12, 13, 14, 15, 16},
    {16, 16, 16, 12, 13, 14, 15, 16},
    { 8,  9, 10, 16, 16, 16, 14, 15},
    { 9, 10, 11, 13, 14, 15, 13,  8},
    {11, 12, 13, 16, 16, 16,  8, 10},
    {12, 13, 14, 15, 16, 16,  9, 11},
    {13, 14, 15,  8,  9, 10, 16, 12},
    {14, 15, 16,  9, 10, 11, 16, 13}};
static const uint32_t MM_NEG[10] = {0u, 0u, 0u, 0u, 0u, 0u, 1u, 1u, 1u, 1u};
void secp256r1_mmod_model(const uint32_t in[16], uint32_t out[16]) {
    uint32_t c[17];
    uint32_t r[8], a[8], d[8];
    uint32_t carry; /* signed top word t, two's complement */
    int i, k;
    for (i = 0; i < 16; i++) c[i] = in[i];
    c[16] = 0;
    for (i = 0; i < 8; i++) r[i] = c[i];
    carry = 0;
    /* ten 256-bit add/sub passes: R = R + (term XOR sm) + neg; carry = carry + cout - neg */
    for (k = 0; k < 10; k++) {
        uint32_t neg = MM_NEG[k];
        uint32_t sm = (uint32_t)0 - neg;
        uint64_t s = neg;
        for (i = 0; i < 8; i++) {
            s = s + (uint64_t)r[i] + (uint64_t)(c[MM_TERM[k][i]] ^ sm);
            r[i] = (uint32_t)s;
            s >>= 32;
        }
        carry = carry + (uint32_t)s - neg;
    }
    /* X == t*2^256 + R (mod p), t in [-4, 6]. Eight constant-time correction steps:
       if t < 0 add p; else if t != 0 or R >= p subtract p; else keep. */
    for (k = 0; k < 8; k++) {
        uint64_t sa = 0, sd = 0;
        uint32_t b, ca, isneg, nz, dosub, doadd, ms, ma;
        for (i = 0; i < 8; i++) {
            sa = sa + (uint64_t)r[i] + (uint64_t)MM_P256[i];
            a[i] = (uint32_t)sa;
            sa >>= 32;
            sd = (uint64_t)r[i] - (uint64_t)MM_P256[i] - sd;
            d[i] = (uint32_t)sd;
            sd = (sd >> 32) & 1u;
        }
        ca = (uint32_t)sa;
        b = (uint32_t)sd;
        isneg = carry >> 31;
        nz = (carry | ((uint32_t)0 - carry)) >> 31;
        doadd = isneg;
        dosub = (1u - isneg) & (nz | (1u - b));
        ma = (uint32_t)0 - doadd;
        ms = (uint32_t)0 - dosub;
        for (i = 0; i < 8; i++)
            r[i] = (a[i] & ma) | (d[i] & ms) | (r[i] & ~(ma | ms));
        carry = carry + (ca & doadd) - (b & dosub);
    }
    for (i = 0; i < 8; i++) out[i] = r[i];
    for (i = 8; i < 16; i++) out[i] = 0;
}

/* ---- end model ---- */


static uint32_t red_xs32(uint32_t *s) {
  uint32_t x = *s;
  x ^= x << 13; x ^= x >> 17; x ^= x << 5;
  return *s = x;
}

static const uint32_t RED_CORNERS[RED_NCORNER] = { 0x00000000u, 0xffffffffu, 0xaaaaaaaau, 0x55555555u };

/* Vector i: the first RED_NCORNER are uniform corner patterns, the rest are
   drawn from the PRNG. The PRNG is advanced only by the random vectors, so
   both harnesses stay in lockstep. */
static void red_fill(long i, uint32_t *seed, uint32_t *in) {
  int w;
  if (i < RED_NCORNER) {
    for (w = 0; w < RED_WORDS; w++) in[w] = RED_CORNERS[i];
  } else {
    for (w = 0; w < RED_WORDS; w++) in[w] = red_xs32(seed);
  }
}

static uint32_t red_hash(uint32_t h, const uint32_t *v, int n) {
  int w, b;
  for (w = 0; w < n; w++)
    for (b = 0; b < 4; b++) {
      h ^= (v[w] >> (8 * b)) & 0xffu;
      h *= 16777619u;
    }
  return h;
}


int main(void) {
  uint32_t in[RED_WORDS], out[RED_WORDS];
  uint32_t seed = 0xc0ffeeu, h = 2166136261u;
  long i, w, blk = 0;
  (void)blk;

  for (i = 0; i < RED_NVEC; i++) {
    red_fill(i, &seed, in);
    memset(out, 0, sizeof out);
    secp256r1_mmod_model(in, out);
    h = red_hash(h, out, RED_WORDS);
    if ((i + 1) % RED_BLOCK == 0 || i + 1 == RED_NVEC) {
      printf("%08x\n", h);
    }
  }
  return 0;
}
